<?php
namespace App\Http\Controllers;use App\Exports\TransportProgrammingExport;use App\Models\TransportService;use Barryvdh\DomPDF\Facade\Pdf;use Illuminate\Http\Request;use Maatwebsite\Excel\Facades\Excel;
class TransportProgrammingReportController extends Controller{public function pdf(Request$r){$services=$this->query($r)->get();$company=$r->user()->company;return Pdf::loadView('pdf.transport_programming',compact('services','company'))->setPaper('a4','landscape')->download('programacion-transporte.pdf');}public function excel(Request$r){return Excel::download(new TransportProgrammingExport($r->user()->company_id,$r->only(['from','to','transport_route_id','planned_vehicle_id','planned_driver_id','status'])),'programacion-transporte.xlsx');}private function query(Request$r){$q=TransportService::forCompany($r->user()->company_id)->with(['vehicle','driver.employee','monitor.employee','passengers'])->orderBy('scheduled_start_at');if($r->filled('from'))$q->whereDate('service_date','>=',$r->from);if($r->filled('to'))$q->whereDate('service_date','<=',$r->to);foreach(['transport_route_id','planned_vehicle_id','planned_driver_id','status']as$f)if($r->filled($f))$q->where($f,$r->$f);return$q;}}
